  "seed_edits": [
    {
      "table": "teams",
      "op": "insert",
      "key": {"team_id": "T02ORBIT"},
      "values": {"team_id": "T02ORBIT", "team_name": "Orbit Labs"},
      "reason": "Needed as the distractor workspace referenced by orbit_workspace role; must exist as a real, separate workspace to make the negative plausible."
    },
    {
      "table": "users",
      "op": "insert",
      "key": {"user_id": "U_ORBIT_ELENA"},
      "values": {
        "user_id": "U_ORBIT_ELENA",
        "username": "elena.voss",
        "display_name": "Elena",
        "real_name": "Elena Voss",
        "email": "elena@orbitlabs.io",
        "is_bot": false,
        "timezone": "Europe/Berlin"
      },
      "reason": "Author of the distractor OOM message in the Orbit Labs workspace, needed for orbit_alert_message role."
    },
    {
      "table": "channels",
      "op": "insert",
      "key": {"channel_id": "C_ORBIT_INFRA"},
      "values": {
        "channel_id": "C_ORBIT_INFRA",
