      "values": {"channel_id": "C_ORBIT_INFRA", "user_id": "U_ORBIT_ELENA"},
      "reason": "Elena must be a member of the channel she posts in, for coherence of the distractor conversation."
    },
    {
      "table": "user_teams",
      "op": "insert",
      "key": {"user_id": "U_ORBIT_ELENA", "team_id": "T02ORBIT"},
      "values": {"user_id": "U_ORBIT_ELENA", "team_id": "T02ORBIT", "role": "member"},
      "reason": "Needed workspace_membership row for orbit_membership negative role, belonging to the wrong workspace."
    },
    {
      "table": "messages",
      "op": "insert",
      "key": {"message_id": "1706200000.000001"},
      "values": {
        "message_id": "1706200000.000001",
        "channel_id": "C_ORBIT_INFRA",
        "user_id": "U_ORBIT_ELENA",
        "message_text": "GPU nodes hitting OOM during batch resize on the autoscaler group, checking memory limits now.",
        "type": "message",
        "ts": "1706200000.000001"
      },
      "reason": "Distractor message about a similarly-themed OOM issue, authored by a different person in a different channel/workspace, needed for orbit_alert_message role."
    }
  ],
  "bindings": {
    "alert_message": ["1706000208.000000"],
    "alert_channel": ["C_INFRA"],
    "alert_author": ["U_PRIYA"],
    "target_workspace": ["T01WORKSPACE"],
    "priya_membership": [{"user_id": "U_PRIYA", "team_id": "T01WORKSPACE"}],
    "lukas_membership": [{"user_id": "U_LUKAS", "team_id": "T01WORKSPACE"}],
    "robert_admin_membership": [{"user_id": "U03ROBERT23", "team_id": "T01WORKSPACE"}],
    "orbit_alert_message": ["1706200000.000001"],
