  "selectors": [
    {
      "root_table": "user_teams",
      "scope": [
        {"field": "user_id", "op": "in", "value": ["U_PRIYA", "U_LUKAS", "U03ROBERT23"]}
      ],
      "focal": {
        "path": ["user_teams", "teams", "channels", "messages", "users"],
        "joins": ["user_teams.team_id", "channels.team_id", "messages.channel_id", "messages.user_id"],
        "filters": [
          {"node": 4, "field": "real_name", "op": "eq", "value": "Priya Sharma"},
